<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Domain;

use Civi\Lughauth\Shared\Context;

final class OidcUrlBuilder
{
    private readonly string $baseUrl;

    public function __construct(Context $context)
    {
        $this->baseUrl = rtrim($context->getBaseUrl(), '/') . '/oauth/openid/';
    }

    public function authorizeUrl(
        AuthenticationRequest $client,
        string $tenant,
        string $state,
        string $nonce,
        array $extra = [],
        string $suffix = ''
    ): string {
        return $this->buildUrl(
            $client,
            $this->baseAuthorizeUrl($tenant),
            $state,
            $nonce,
            $extra,
            $suffix
        );
    }

    public function checkSessionUrl(
        AuthenticationRequest $client,
        string $tenant,
        string $state,
        string $nonce,
        array $extra = [],
        string $suffix = ''
    ): string {
        return $this->buildUrl(
            $client,
            $this->baseCheckSessionUrl($tenant),
            $state,
            $nonce,
            $extra,
            $suffix
        );
    }

    public function registerUserUrl(
        AuthenticationRequest $client,
        string $tenant,
        string $state,
        string $nonce,
        string $suffix = '',
        array $extra = []
    ): string {
        return $this->authorizeUrl(
            $client,
            $tenant,
            $state,
            $nonce,
            array_merge(['step' => StepName::REGISTER_USER->value, 'verify_send' => 'true'], $extra),
            $suffix
        );
    }

    public function recoverPassUrl(
        AuthenticationRequest $client,
        string $tenant,
        string $state,
        string $nonce,
        string $suffix = '',
        array $extra = []
    ): string {
        return $this->authorizeUrl(
            $client,
            $tenant,
            $state,
            $nonce,
            array_merge(['step' => StepName::RECOVER_PASS->value, 'recover_send' => 'true'], $extra),
            $suffix
        );
    }

    private function baseAuthorizeUrl(string $tenant): string
    {
        return $this->baseUrl . $tenant . '/authorize';
    }

    private function baseCheckSessionUrl(string $tenant): string
    {
        return $this->baseUrl . $tenant . '/check-session';
    }

    private function buildUrl(
        AuthenticationRequest $client,
        string $baseUrl,
        string $state,
        string $nonce,
        array $extra,
        string $suffix
    ): string {
        $params = [
            'client_id' => $client->client->id,
            'scope' => $client->scope,
            'state' => $state,
            'nonce' => $nonce,
            'audience' => implode(',', $client->audiences),
            'redirect_uri' => $client->redirect,
            'response_type' => (string) $client->responseType,
        ];

        foreach ($extra as $key => $value) {
            $params[$key] = $value;
        }

        $query = http_build_query($params, '', '&', PHP_QUERY_RFC3986);
        $url = $baseUrl . '?' . $query;

        if ($suffix !== '') {
            $url .= $suffix;
        }

        return $url;
    }
}
